insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"Middle West Spirits Dark Pumpernickel Rye","rar":"shelf","f":"Middle West","x":"Dark Pumpernickel Rye","p":96.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"rye","mb":null,"st":"rye","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":null,"u":"https://middlewestspirits.com/spirits/whiskey/middle-west-spirits-dark-pumpernickel-rye-whiskey/","pr":"Middle West Spirits","mk":"f8d14bdb-254e-4489-95c8-14f8a027b425"},{"n":"Middle West Spirits Straight Wheat Whiskey","rar":"shelf","f":"Middle West","x":"Straight Wheat Whiskey","p":92.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"wheated","mb":null,"st":"wheat_whiskey","bib":false,"bp":false,"fin":null,"msrp":null,"core":true,"al2":[],"img":null,"u":"https://middlewestspirits.com/spirits/whiskey/middle-west-spirits-straight-wheat-whiskey/","pr":"Middle West Spirits","mk":"f8d14bdb-254e-4489-95c8-14f8a027b425"},{"n":"Middle West Spirits Double Cask Collection: Ported Pumpernickel Rye","rar":"limited","f":"Middle West","x":"Double Cask Collection: Ported Pumpernickel Rye","p":99.5,"ay":5.0,"al":"5 yr","nas":false,"et":"standard","ms":"rye","mb":null,"st":"rye","bib":false,"bp":false,"fin":"Tawny Port Casks","msrp":null,"core":false,"al2":[],"img":null,"u":"https://middlewestspirits.com/spirits/whiskey/mws-ported-pumpernickel-rye-whiskey/","pr":"Middle West Spirits","mk":"f8d14bdb-254e-4489-95c8-14f8a027b425"},{"n":"Middle West Spirits Double Cask Collection: Oloroso Wheat","rar":"limited","f":"Middle West","x":"Double Cask Collection: Oloroso Wheat","p":100.0,"ay":null,"al":null,"nas":false,"et":"standard","ms":"wheated","mb":null,"st":"wheat_whiskey","bib":false,"bp":false,"fin":"Oloroso Sherry Casks","msrp":null,"core":false,"al2":[],"img":null,"u":"https://middlewestspirits.com/spirits/whiskey/mws-oloroso-wheat-whiskey/","pr":"Middle West Spirits","mk":"f8d14bdb-254e-4489-95c8-14f8a027b425"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');
